if (
  operationType !== 'read' &&
  !isInWorkingDir &&
  isPathInSandboxWriteAllowlist(resolvedPath)
) {
  return {
    allowed: true,
    decisionReason: {
      type: 'other',
      reason: 'Path is in sandbox write allowlist',
    },
